server_scripts.script:
# Auto-generated by setup-erpnext.mjs — share assigned Lead/Opportunity with the assignee
TRACKED = ["Lead","Opportunity"]
if doc.reference_type in TRACKED and doc.allocated_to:
    if not frappe.db.exists("DocShare", {
        "share_doctype": doc.reference_type,
        "share_name": doc.reference_name,
        "user": doc.allocated_to,
    }):
        frappe.get_doc({
            "doctype": "DocShare",
            "user": doc.allocated_to,
            "share_doctype": doc.reference_type,
            "share_name": doc.reference_name,
            "read": 1,
            "write": 1,
        }).insert(ignore_permissions=True)

# Auto-generated by setup-erpnext.mjs — revoke share when assignment is cancelled
if doc.status == "Cancelled":
    TRACKED = ["Lead","Opportunity"]
    if doc.reference_type in TRACKED and doc.allocated_to:
        others = frappe.db.exists("ToDo", {
            "reference_type": doc.reference_type,
            "reference_name": doc.reference_name,
            "allocated_to": doc.allocated_to,
            "status": ["!=", "Cancelled"],
            "name": ["!=", doc.name],
        })
        if not others:
            ds = frappe.db.get_value("DocShare", {
                "share_doctype": doc.reference_type,
                "share_name": doc.reference_name,
                "user": doc.allocated_to,
            })
            if ds:
                frappe.delete_doc("DocShare", ds, ignore_permissions=True)

# Auto-generated by setup-erpnext.mjs — revoke share when assignment ToDo is deleted
TRACKED = ["Lead","Opportunity"]
if doc.reference_type in TRACKED and doc.allocated_to:
    others = frappe.db.exists("ToDo", {
        "reference_type": doc.reference_type,
        "reference_name": doc.reference_name,
        "allocated_to": doc.allocated_to,
        "status": ["!=", "Cancelled"],
        "name": ["!=", doc.name],
    })
    if not others:
        ds = frappe.db.get_value("DocShare", {
            "share_doctype": doc.reference_type,
            "share_name": doc.reference_name,
            "user": doc.allocated_to,
        })
        if ds:
            frappe.delete_doc("DocShare", ds, ignore_permissions=True)
